import { test, expect } from '@playwright/test';

test.describe('Mobile Search Bar Expansion', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should expand search bar on focus on mobile devices', async ({ page }) => {
    // Verify search bar is collapsed by default
    const searchInput = page.getByRole('searchbox');
    await expect(searchInput).toBeVisible();
    await expect(searchInput).toHaveValue('');

    // Verify search icon is visible and clickable
    const searchIcon = page.getByRole('button', { name: /search/i });
    await expect(searchIcon).toBeVisible();

    // Verify search results container is collapsed
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();
    await expect(searchResults).toHaveClass(/collapsed/i);

    // Setup mobile viewport
    await page.setViewportSize({ width: 375, height: 812 });

    // Focus on search input
    await searchInput.click();

    // Verify search bar expands
    await expect(searchInput).toHaveValue('');
    await expect(searchInput).toBeFocused();

    // Verify search icon is still visible
    await expect(searchIcon).toBeVisible();

    // Verify search results container is expanded
    await expect(searchResults).not.toHaveClass(/collapsed/i);
    await expect(searchResults).toBeVisible();

    // Verify search results are visible
    const resultItem = page.getByText('Result 1');
    await expect(resultItem).toBeVisible();

    // Verify search input has placeholder
    await expect(searchInput).toHavePlaceholder('Search...');

    // Verify search input has correct label
    const searchLabel = page.getByLabel(/search/i);
    await expect(searchLabel).toBeVisible();
  });

  test('should collapse search bar when clicking outside on mobile devices', async ({ page }) => {
    // Verify search bar is expanded
    const searchInput = page.getByRole('searchbox');
    await expect(searchInput).toBeVisible();
    await expect(searchInput).toHaveValue('');

    // Verify search icon is visible and clickable
    const searchIcon = page.getByRole('button', { name: /search/i });
    await expect(searchIcon).toBeVisible();

    // Verify search results container is expanded
    const searchResults = page.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();
    await expect(searchResults).not.toHaveClass(/collapsed/i);

    // Setup mobile viewport
    await page.setViewportSize({ width: 375, height: 812 });

    // Focus on search input
    await searchInput.click();

    // Verify search bar is expanded
    await expect(searchInput).toHaveValue('');
    await expect(searchInput).toBeFocused();

    // Verify search results are visible
    const resultItem = page.getByText('Result 1');
    await expect(resultItem).toBeVisible();

    // Click outside search bar to trigger collapse
    const outsideElement = page.locator('body');
    await outsideElement.click();

    // Verify search bar collapses
    await expect(searchInput).toHaveValue('');
    await expect(searchInput).not.toBeFocused();

    // Verify search results container is collapsed
    await expect(searchResults).toHaveClass(/collapsed/i);
    await expect(searchResults).not.toBeVisible();

    // Verify search input has placeholder
    await expect(searchInput).toHavePlaceholder('Search...');

    // Verify search input has correct label
    const searchLabel = page.getByLabel(/search/i);
    await expect(searchLabel).toBeVisible();
  });
});
